def to_float(x):
    """
    Excel'den gelen '17,957,131' / '17.957.131' gibi değerleri sayıya çevirir.
    (Ondalık kısmı yok varsayılır; finansal tutarlar için tipik.)
    """
    if pd.isna(x): 
        return np.nan
    s = str(x).strip().replace(",", "").replace(".", "")
    if s in ("", "-", "None", "nan"): 
        return np.nan
    try:
        return float(s)
    except Exception:
        return np.nan

